		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	if input.Name == "" {
		writeError(w, http.StatusBadRequest, "name is required")
		return
	}

	if input.SlotID != nil {
		slot, err := h.queries.GetSlot(r.Context(), *input.SlotID)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusBadRequest, "slot not found")
				return
			}
			writeError(w, http.StatusInternalServerError, err.Error())
			return
		}
		input.MachineID = &slot.MachineID
	}

	part, err := h.queries.CreatePart(r.Context(), partParamsFromInput(input))
	if err != nil {
		if strings.Contains(err.Error(), "UNIQUE") {
			writeError(w, http.StatusBadRequest, "slot already filled")
			return
		}
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}
	writeJSON(w, http.StatusCreated, newPartResponse(part))
}

func (h *Handler) GetPart(w http.ResponseWriter, r *http.Request) {
	id, err := parseID(r, "id")
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid id")
		return
	}
	part, err := h.queries.GetPart(r.Context(), id)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not found")
			return
		}
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}

	resp := newPartResponse(part)
	if part.MachineID.Valid {
		machine, err := h.queries.GetMachine(r.Context(), part.MachineID.Int64)
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusInternalServerError, err.Error())
			return
		}
		if err == nil {
			resp.Machine = &MachineSummary{
				ID:   machine.ID,
				Name: machine.Name,
			}
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

func (h *Handler) UpdatePart(w http.ResponseWriter, r *http.Request) {
	id, err := parseID(r, "id")
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid id")
		return
	}
	var input PartInput
	if err := decodeJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	if input.Name == "" {
		writeError(w, http.StatusBadRequest, "name is required")
		return
	}

	if input.SlotID != nil {
		slot, err := h.queries.GetSlot(r.Context(), *input.SlotID)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusBadRequest, "slot not found")
				return
			}
			writeError(w, http.StatusInternalServerError, err.Error())
			return
		}
		input.MachineID = &slot.MachineID
	}

	part, err := h.queries.UpdatePart(r.Context(), updatePartParamsFromInput(id, input))
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not found")
			return
		}
		if strings.Contains(err.Error(), "UNIQUE") {
			writeError(w, http.StatusBadRequest, "slot already filled")
			return
		}
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}
	writeJSON(w, http.StatusOK, newPartResponse(part))
}

func (h *Handler) DeletePart(w http.ResponseWriter, r *http.Request) {
	id, err := parseID(r, "id")
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid id")
		return
	}
	if err := h.queries.DeletePart(r.Context(), id); err != nil {
		writeError(w, http.StatusInternalServerError, err.Error())
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

